parameters.jsonBody:
={{ JSON.stringify({
  model: 'claude-sonnet-5',
  max_tokens: 1500,
  system: $vars.AGENT_SYSTEM_PROMPT,
  messages: [{ role: 'user', content: `Task: prospect research

Inputs:
prospect_name: ${$json['Prospect name']}
profile_url: ${$json['Profile / company URL'] || 'none provided'}
channel: ${$json['Where you found them (channel)']}
known_context: ${$json['Anything you already know'] || 'none'}

Produce exactly two sections with these headings:
Prospect Summary
---
Outreach Draft` }]
}) }}

parameters.jsCode:
const text = $input.first().json.content?.[0]?.text ?? '';
const [summaryPart, draftPart] = text.split(/---|\n(?=Outreach Draft)/i);
const clean = (s, heading) => (s ?? '').replace(new RegExp('^\\s*' + heading + '\\s*:?\\s*', 'i'), '').trim();
return [{ json: {
  prospect_name: $('New prospect (form)').first().json['Prospect name'],
  channel: $('New prospect (form)').first().json['Where you found them (channel)'],
  prospect_summary: clean(summaryPart, 'Prospect Summary'),
  outreach_draft: clean(draftPart, 'Outreach Draft'),
} }];

parameters.message:
={{ $json.outreach_draft + '

—
Staged for your approval — nothing has been sent. [orion-self-install v0.1.0]' }}
